const fs = require('fs');
const { chapter, M, ROOT } = require('./lib.js');
const { MathRadical, MathSubSuperScript, MathSubScript } = require('docx');
const L = chapter(3, 'CHAPTER 3: METHODOLOGY', 'CHAPTER 3 thesis.docx');
const D = JSON.parse(fs.readFileSync(`${ROOT}/results/v2/chapter3_data.json`, 'utf8'));
const A = JSON.parse(fs.readFileSync(`${ROOT}/results/thesis/ch5_data.json`, 'utf8')).F;
const mins = (s) => `${(s / 60).toFixed(1)} min`;
const secs = (s) => (s < 1 ? '< 1 s' : s >= 120 ? mins(s) : `${s.toFixed(0)} s`);
const F = D.F, T = D.T;
const env = A.env, req = A.requirements, st = A.stages;
const gib = (Number(env['local memory (bytes)']) / 2 ** 30).toFixed(0);
const { R, sub, sup, frac, fn, par, sq, sum } = M;
const n = L.n, pct = L.pct, add = L.add, P = (s, o) => L.P(s, o), H1 = L.H1, H2 = L.H2, H3 = L.H3, table = L.table, caption = L.caption, afterTable = L.afterTable, figure = L.figure;
const ref = (l) => L.ref(l);
const cit = (...k) => L.cit(...k), citN = (k) => L.citN(k);
const lgbS = F.par['baselines|LightGBM'];
const lgb = { n: /n_estimators=(\d+)/.exec(lgbS)[1], lr: /learning_rate=([\d.]+)/.exec(lgbS)[1], leaves: /num_leaves=(\d+)/.exec(lgbS)[1], es: /early stopping (\d+) rounds/.exec(lgbS)[1] };
const EQ = { ident: 1, pool: 2, bce: 3, supcon: 4, comb: 5, perAnchor: 6, floor: 7, acc: 8, sens: 9, spec: 10, prec: 11, f1: 12, mcc: 13, auroc: 14, auprc: 15, delong: 16, mcnemar: 17, bh: 18, mde: 19 };
const E = (k) => `3.${EQ[k]}`;   // template prints equation numbers bare: 'Equation 3.2'
let eqSeen = 0;
function eq(key, ...children) { eqSeen += 1; if (EQ[key] !== eqSeen) throw new Error(`equation order ${key}`); return M.eqPara(`3.${EQ[key]}`, ...children); }
function P_(pair, key) { return Number(F.pairs[pair][key]).toLocaleString('en-US'); }
// ====================================================================== TITLE
add(H1('CHAPTER 3: METHODOLOGY'));
add(P(`This chapter describes the data, the evaluation protocol, the feature representations, the models, the loss functions, the metrics and the statistical procedures used to test whether a supervised contrastive objective improves anti-inflammatory peptide (AIP) prediction. The order follows the order in which the questions arose in the work: the datasets and their provenance are established first, because every later result depends on what the training and test files contain; the evaluation regimes follow from that audit; the models and losses are then defined; and the statistical protocol closes the chapter. All numbers in this chapter are taken from files produced by the analysis code and stored with the project, and a small number of items that those files do not contain are marked as to-do items in the text.`));

// ====================================================================== 3.1
add(P(`Figure ${ref('fig:method')} sets out the whole procedure, from the three distributed files to the three evaluation regimes under which every model is scored. Each step is described in the section named beside it.`));
add(figure('fig:method', 'fig3_1_methodology.png', 'Overall methodology. The three distributed files are first traced to their published sources and audited for duplication, label conflict and training-test overlap; cleaning produces Benchmark_clean; every model is then scored under three evaluation regimes that progressively remove overlap between the training collection and the test sets. Hatching distinguishes the audit steps (dotted) and the evaluation regimes (diagonal); dashed outlines mark the modelling steps.', 470));

add(H2('3.1 Datasets'));
add(P(`Three peptide collections were used: one training collection, Benchmark_Dataset, and two independent test collections, Ind_425 and Ind_1049. Each is distributed as a FASTA file in which the class is encoded in the header; a header containing the word "positive" (in either of the two header formats in use) was read as an AIP (label 1) and every other header as a non-AIP (label 0). Sequences were normalised by removing whitespace and converting to upper case, and every sequence in every file used in this chapter was checked against the twenty standard amino acids; ${F.nonstandard_total} of the sequences in the ${F.n_datasets_checked} files examined contained a non-standard residue.`));
add(P(`<b>Provenance.</b> The provenance of each file was established before any modelling, by comparing it with the published datasets from which it appears to derive. The AIPpred datasets ${cit('manavalan2018')} were downloaded from the authors' web page, and the AntiInflam datasets ${cit('gupta2017')} and the PreAIP datasets ${cit('khatun2019')} were retrieved from archived snapshots of the authors' servers, because those servers could not be reached; the address, size and SHA-256 digest of every downloaded file are recorded in the project (results/external_sources.csv). The comparison showed that Ind_1049 is the independent set published with AIPpred: its ${n(F.ap_ind_pos + F.ap_ind_neg)} sequences, their labels and their order are identical to the published file, and the same set was used as the test set of PreAIP. Ind_425 is the validation set published with AntiInflam, again identical in sequences, labels and order. The AntiInflam paper states that this set contains 173 positive and ${F.ai_val_neg + 1} negative peptides, but its own totals (1,261 negative peptides, of which 1,009 were assigned to training) imply ${F.ai_val_neg}, and the distributed file contains ${F.ai_val_neg}; the local file equals the distributed file exactly, so no sequence is missing.`));
add(P(`Benchmark_Dataset is not a single published set. It contains ${n(F.prov.aippred_bench_unique - F.prov.aippred_bench_seqs_absent_locally)} of the ${n(F.prov.aippred_bench_unique)} sequences of the AIPpred benchmark (${n(F.ap_bench_pos)} AIPs and ${n(F.ap_bench_neg)} non-AIPs; ${F.prov.aippred_bench_seqs_absent_locally} sequences are absent) together with ${F.prov.n_extras_not_in_aippred_bench} further sequences, all of which belong to the AntiInflam training set (${F.ai_train_pos} AIPs and ${n(F.ai_train_neg)} non-AIPs). Of the ${F.lin.ai_only} AntiInflam training sequences that are not in the AIPpred benchmark, ${F.lin.ai_only_present} are present in Benchmark_Dataset and ${F.lin.ai_only_absent} are absent; the files do not record why. None of the added sequences occurs in the AntiInflam validation set. Both source resources drew their peptides from the Immune Epitope Database ${cit('vita2019')}. The provenance of the three files is summarised in Table ${ref('tab:provenance')} and the structure of the resources in Figure ${ref('fig:lineage')}.`));
add(P(`<b>Composition.</b> The composition of the three files and of the cleaned training collection derived from them (Section 3.3) is given in Table ${ref('tab:dataset_composition')}. Peptide lengths range from ${F.i425.len_min} to ${F.bench.len_max} residues, with a mean of about ${F.bench.len_mean.toFixed(1)}. The proportion of AIPs is ${pct(F.bench.pos_rate)} in Benchmark_Dataset, ${pct(F.i425.pos_rate)} in Ind_425 and ${pct(F.i1049.pos_rate)} in Ind_1049, a moderate and consistent class imbalance that is taken into account in the loss function (Section 3.7) and in the choice of the primary metric (Section 3.8).`));
add(caption('tab:dataset_composition', 'Composition of the three distributed files and of the cleaned training collection (Benchmark_clean, Section 3.3). Source: results/data_audit.csv.'));
add(table(T.dataset_composition, [2000, 1000, 800, 1000, 900, 900, 1500, 1260], { right: [1, 2, 3, 4, 5, 7] }), afterTable());
add(caption('tab:provenance', 'Provenance of the three local files, established by comparison with the downloaded original files. Source: results/provenance.csv.'));
add(table(T.provenance, [1500, 3700, 2700, 1460]), afterTable());
add(figure('fig:lineage', 'fig3_2_lineage.png', 'Provenance of the three files and the origin of the overlap. A: inside each resource the training and test sets share no sequence. B: the distributed training file combines the AIPpred benchmark with 612 AntiInflam training sequences, so each resource\'s test set meets the other resource\'s training data, and 211 of the 425 sequences of Ind_425 and 298 of the 1,049 of Ind_1049 occur in the training file. Counts from results/tables/T3.5_cross_benchmark_leakage.csv and results/provenance.csv.', 480));

// ====================================================================== 3.2
add(H2('3.2 Data integrity audit'));
add(P(`The audit asked two questions of the distributed files: whether the training collection is internally consistent, and whether the independent test sets are independent of it. Exact-match overlap was computed on unique, normalised sequences and the labels of shared sequences were compared; near-duplicate similarity is treated separately in Section 3.4.`));
add(H3('3.2.1 Label conflicts within the training collection'));
add(P(`Benchmark_Dataset contains ${n(F.bench.n)} rows but only ${n(F.bench.unique)} unique sequences. The difference is accounted for entirely by ${F.bench.dup_seqs} sequences that each occur twice, and in every one of these cases the two copies carry opposite labels: the ${F.bench.dup_seqs} duplicated sequences and the ${F.bench.conflicts} label conflicts are the same set. Deduplication and conflict resolution therefore coincide (Table ${ref('tab:conflicts')}). The origin of the conflicts is visible in the source files. The AIPpred benchmark and the AntiInflam training set share ${F.lin.shared} sequences; ${F.lin.same} of them carry the same label in both resources and ${F.lin.opp} carry opposite labels, and these ${F.lin.opp} are exactly the ${F.lin.opp_equal_local_conf} sequences that occur twice in Benchmark_Dataset. Neither source file contains a conflicted sequence internally (${F.lin.ap_internal_conf} in the AIPpred benchmark and ${F.lin.ai_internal_conf} in the AntiInflam training set). The conflicts thus arise when the two resources are combined, and they record that the same peptide is labelled differently by the two sources; the files do not record the evidence behind either label, so it is not possible to say from them which label is correct.`));
add(caption('tab:conflicts', 'Duplicates and label conflicts in Benchmark_Dataset and their origin. Sources: results/data_audit.csv and results/v2/lineage_shared_training.csv.'));
add(table(T.conflicts, [7000, 2360], { right: [1] }), afterTable());
add(H3('3.2.2 Overlap between training and independent sets, by direction'));
add(P(`The overlap between training and independent sets is reported separately for each direction, because the two directions are different findings with different sources (Table ${ref('tab:overlap')}). <b>Finding 1:</b> the AIPpred benchmark contains ${P_('ap_ai', 'exact')} of the ${P_('ap_ai', 'n_test')} sequences of the AntiInflam validation set (${pct(F.pairs.ap_ai.share)}); ${P_('ap_ai', 'same')} of the shared sequences carry the same label in both files and ${P_('ap_ai', 'opp')} carry opposite labels. <b>Finding 2:</b> the AntiInflam training set contains ${P_('ai_ap', 'exact')} of the ${P_('ai_ap', 'n_test')} sequences of the AIPpred independent set (${pct(F.pairs.ai_ap.share)}); ${P_('ai_ap', 'same')} carry the same label and ${P_('ai_ap', 'opp')} carry opposite labels. The two independent sets also share ${F.ind_ind.exact} sequences with each other (${F.ind_ind.same} with the same label and ${F.ind_ind.opp} with opposite labels).`));
add(P(`Each source partition is internally disjoint. The AIPpred benchmark and the AIPpred independent set share ${F.pairs.ap_ap.exact} sequences, and the AntiInflam training set and the AntiInflam validation set share ${F.pairs.ai_ai.exact} sequences. The overlaps therefore appear only where the two resources meet across a training and test boundary. Finding 1 exists between the unmodified AIPpred benchmark and the AntiInflam validation set, so it does not depend on the construction of Benchmark_Dataset; Finding 2 appears because Benchmark_Dataset contains AntiInflam training sequences, all ${F.pairs.ai_ap.exact} of the shared sequences being among the ${F.prov.n_extras_not_in_aippred_bench} added ones. Benchmark_Dataset, as the union of the two, inherits both, and the counts for the local files are accordingly the same as those in Table ${ref('tab:overlap')}: ${F.pairs.ap_ai.exact} sequences of Ind_425 and ${F.pairs.ai_ap.exact} of Ind_1049 occur in the training collection. Neither overlap count depends on whether the label-conflicted sequences are removed first, because none of the ${F.bench.conflicts} conflicted sequences occurs in either test set.`));
add(P(`These measurements describe the distributed files. They are not a statement that any published analysis was incorrect: each resource is internally disjoint as published, the two were curated separately from the same underlying database, and the overlap follows from combining sequences across them. Whether a given later analysis used the combined file, a filtered version of it, or a different split cannot be determined from the files and is not asserted here. Table ${ref('tab:overlap')} also reports the number of independent-set sequences whose alignment identity to some training sequence is at least 0.9; for the two within-resource pairs this is ${F.pairs.ap_ap.id09} of ${n(F.pairs.ap_ap.n_test)} sequences (${pct(F.pairs.ap_ap.id09_share)}) for AIPpred and ${F.pairs.ai_ai.id09} of ${F.pairs.ai_ai.n_test} (${pct(F.pairs.ai_ai.id09_share)}) for AntiInflam. These counts describe near-duplicates, not exact copies, and are reported without attributing a cause; the small AIPpred figure is consistent with differences between the identity measure used here and the one used in the clustering step that AIPpred reports.`));
add(caption('tab:overlap', 'Exact overlap between each training set and each independent set, by direction, with the number of independent-set sequences at identity of 0.9 or more to the training set. Percentages are of the independent set. Source: results/tables/T3.5_cross_benchmark_leakage.csv.'));
add(table(T.overlap, [2900, 850, 700, 700, 800, 850, 1000, 1560], { right: [1, 2, 3, 4, 5, 6, 7], size: 17 }), afterTable());

{ const hrows = fs.readFileSync(`${ROOT}/results/v2/aipfusion_repo_check.csv`, 'utf8').trim().split('\n').slice(1).map((l) => l.split(','));
  const sizes = { Benchmark_Dataset: fs.statSync(`${ROOT}/data/raw/Benchmark_Dataset.fasta`).size, Ind_1049: fs.statSync(`${ROOT}/data/raw/Ind_1049.fasta`).size, Ind_425: fs.statSync(`${ROOT}/data/raw/Ind_425.fasta`).size };
  add(P(`The data availability statement of the AIPFusion-Net paper ${cit('wang2026')} names a public repository (github.com/ChenYH7693/AIPFusion-Net) that holds three data files, Benchmark_Dataset.txt, Ind_1049.txt and Ind_425.txt. These files were downloaded and compared with the local files that are audited in this chapter. <b>The three distributed files are byte-identical, by SHA-256, to the files audited here</b> (Table ${ref('tab:hashes')}). The paper reports a training set of 1,451 AIPs and 2,339 non-AIPs, which agrees with the class counts of Benchmark_Dataset. The overlap quantified in this section is therefore a property of the files in that repository, as it is of the other distributed copies. The experiments of the paper were not repeated, and whether they used exactly these files, or a filtered version of them, cannot be determined from the files; nothing about the paper's analysis is asserted here.`));
  add(caption('tab:hashes', 'SHA-256 digests of the local data files and of the files in the AIPFusion-Net repository, downloaded from raw.githubusercontent.com/ChenYH7693/AIPFusion-Net/main/AIPData/ on 2026-11-26. Source: results/v2/aipfusion_repo_check.csv.'));
  add(table([['File', 'Bytes', 'SHA-256 of the local file', 'SHA-256 of the repository file', 'Identical'], ...hrows.map((r) => [r[0], n(sizes[r[0]]), r[1], r[2], r[3] === 'True' ? 'yes' : 'NO'])], [1500, 800, 2900, 2900, 1260], { size: 14 }), afterTable()); }

// ====================================================================== 3.3
add(H2('3.3 Data cleaning protocol'));
add(P(`Benchmark_Dataset was cleaned in two steps, each producing a fixed file on disk from which every later experiment reads, so that the training collection cannot change silently between analyses (Table ${ref('tab:cleaning')}). In the first step every row of every sequence that carries both labels was removed. In the second step same-label duplicate rows were removed; none remained after the first step. The first step removed ${F.removed_rows} rows (${pct(F.removed_pct)} of ${n(F.bench.n)}, that is, both copies of each of the ${F.bench.conflicts} conflicted sequences) and left ${n(F.clean.n)} sequences, ${n(F.clean.pos)} AIPs and ${n(F.clean.neg)} non-AIPs (${pct(F.clean.pos_rate)} AIPs). This collection is called Benchmark_clean in the remainder of the thesis.`));
add(P(`Both copies of a conflicted sequence were removed, rather than one being retained, for three reasons. First, the sequence carries two contradictory labels and the files contain no information that would allow one to be preferred; keeping either encodes an arbitrary decision as if it were evidence. Second, retaining one copy would give the conflicted sequence a label chosen by file order or by the cleaning code, which would be an uncontrolled source of variation between analyses. Third, a conflicted sequence that is kept teaches a classifier a contradiction: in a flexible model with enough capacity the two labels can be fitted only by memorising the case, which is harmful rather than informative. The cost is small and symmetric between the classes (${F.bench.pos - F.clean.pos} AIP rows and ${F.bench.neg - F.clean.neg} non-AIP rows, ${F.removed_rows} of ${n(F.bench.n)} rows in all), and none of the removed sequences occurs in Ind_425 or Ind_1049, so the cleaning step does not alter either test set.`));
add(caption('tab:cleaning', 'Cleaning of Benchmark_Dataset, with the number of rows after each step. Source: results/data_audit.csv.'));
add(table(T.cleaning, [700, 5060, 1400, 1100, 1100], { right: [2, 3, 4] }), afterTable());

// ====================================================================== 3.4
add(H2('3.4 Evaluation regimes'));
add(P(`Every model was trained once on Benchmark_clean and evaluated on each independent set under three regimes. <b>Regime A</b> uses the independent set exactly as distributed. <b>Regime B</b> removes from the independent set every sequence that also occurs in Benchmark_clean, so that no test sequence has been seen in training. <b>Regime C</b> additionally removes every test sequence whose alignment identity to any training sequence is at least 0.9, which controls for near-duplicates that exact matching cannot detect. The size and class composition of each regime are given in Table ${ref('tab:regimes')}: Regime B leaves ${F.regime.ind_425_regime_b.n} of ${F.regime.ind_425_regime_a.n} sequences of Ind_425 and ${F.regime.ind_1049_regime_b.n} of ${n(F.regime.ind_1049_regime_a.n)} of Ind_1049, and Regime C leaves ${F.regime.ind_425_regime_c.n} and ${F.regime.ind_1049_regime_c.n}.`));
add(P(`All three regimes are reported because they answer different questions. Regime A is the only regime in which results are comparable with those published for the same files, because it reproduces the test conditions that earlier work used; it is therefore the basis for any comparison with published predictors and it is reported in every table. Regime B is the leakage-free estimate that matches what a user of the predictor would experience on peptides that were not in the training data, and the claims of the thesis are made on it. Regime C is a stricter control that asks whether the Regime B result is itself inflated by near-identical sequences. The difference between regimes, computed for every model, measures how much of the apparent performance depends on test sequences that the model had effectively already seen, and it is reported as a result in its own right.`));
add(caption('tab:regimes', 'Size and class composition of the three evaluation regimes for each independent set. Source: results/v2/regime_composition.csv.'));
add(table(T.regimes, [4560, 1200, 1200, 1200, 1200], { right: [1, 2, 3, 4] }), afterTable());
add(figure('fig:regimes', 'fig3_4_regimes.png', 'The three evaluation regimes. Bar length is the number of test sequences that survive each regime, and the hatching distinguishes them; the counts are those of Table ' + ref('tab:regimes') + '. Only the test sets change: the training collection is the same in all three.', 470));

add(H3('3.4.1 Identity screen'));
add(P(`Sequence identity between a test sequence <i>a</i> and a training sequence <i>b</i> was defined as the number of identical residues in a global pairwise alignment divided by the length of the shorter sequence (Equation ${E('ident')}), which is the definition used by the CD-HIT clustering programs ${cit('li2006')}. The alignment was a Needleman–Wunsch global alignment ${cit('needleman1970')} with the BLOSUM62 substitution matrix ${cit('henikoff1992')}, a gap-opening score of ${F.par['identity screen|gap open score']} and a gap-extension score of ${F.par['identity screen|gap extend score']}.`));
add(eq('ident', R('Id(a,b) = '), frac([R('m(a,b)')], [fn('min', [par(R('|a|,|b|'))])])));
add(P(`Here <i>m</i>(<i>a</i>, <i>b</i>) is the number of identical aligned positions. Aligning every test sequence with every training sequence would be wasteful, because almost all pairs are unrelated. Every identical aligned position is part of a common subsequence of <i>a</i> and <i>b</i>, so the length of the longest common subsequence is an upper bound on <i>m</i>(<i>a</i>, <i>b</i>); a pair whose bound divided by the shorter length falls below ${F.par['identity screen|LCS prefilter floor']} cannot reach an identity of ${F.par['identity screen|LCS prefilter floor']} or more and was not aligned. This prefilter is exact, not an approximation: it removes only pairs that cannot meet the threshold. The identity measure was checked against hand-computed pairs in a unit-test suite that accompanies the code.`));
add(P(`All identity figures in this thesis refer to the cleaned benchmark, Benchmark_clean (${n(F.clean.n)} sequences), which is the training collection used for every model. The number of test sequences removed at each threshold is given in Table ${ref('tab:identity')}. At an identity of 1.0 the count exceeds the exact-match count (${F.identity.Ind_425['1.0'].removed} against ${F.identity.Ind_425.exact.removed} for Ind_425), because a short test peptide that is contained entirely within a longer training peptide scores 1.0 under a definition normalised by the shorter sequence. Within-set clustering is not a substitute for a cross-set screen: when each collection was clustered separately in a re-implementation of the CD-HIT procedure at illustrative thresholds of 0.9 for the training collection, 0.8 for Ind_1049 and 0.6 for Ind_425, ${F.within_set_cluster_survivors.i1049} of the ${F.pairs.ai_ap.exact} shared sequences of Ind_1049 and ${F.within_set_cluster_survivors.i425} of the ${F.pairs.ap_ai.exact} shared sequences of Ind_425 remained, since a within-set procedure cannot see the other set (results/tables/T3.5b_cdhit_style_clustering.csv). The CD-HIT programs themselves were not available, and the numbers from this re-implementation are used only for this illustration.`));
add(H3('3.4.2 Shuffled-composition null control'));
add(P(`A high count of near-identical sequences could in principle reflect similar amino acid composition and length rather than shared sequence structure. To test this, every test sequence in each independent set was shuffled, preserving its length and composition and destroying its residue order, and the identity screen was repeated against Benchmark_clean; the procedure was repeated for ${F.null.Ind_425['0.9'].replicates} independent shuffles of each set (Table ${ref('tab:identity')}). Across all ${F.null.Ind_425['0.9'].replicates} replicates no shuffled sequence reached an identity of 0.9 to any training sequence, in either test set, whereas ${F.null.Ind_425['0.9'].observed} of ${F.null.Ind_425['0.9'].n} Ind_425 sequences and ${F.null.Ind_1049['0.9'].observed} of ${n(F.null.Ind_1049['0.9'].n)} Ind_1049 sequences reached it as distributed. At the lower threshold of 0.8 the shuffled sets averaged ${F.null.Ind_425['0.8'].null_mean.toFixed(2)} (maximum ${F.null.Ind_425['0.8'].null_max}) and ${F.null.Ind_1049['0.8'].null_mean.toFixed(2)} (maximum ${F.null.Ind_1049['0.8'].null_max}) sequences against ${F.null.Ind_425['0.8'].observed} and ${F.null.Ind_1049['0.8'].observed} observed. The similarity detected by the screen is therefore a property of the residue order, not a consequence of composition and length alone. The control does not model repetitive or low-complexity peptides, for which order-preserving chance similarity could be higher, and it is a null for the identity screen only.`));
add(caption('tab:identity', 'Identity screen of the independent sets against Benchmark_clean, and the shuffled-composition null control. Sources: results/identity_screen.csv and results/v2/null_control_identity.csv.'));
add(table(T.identity, [1300, 1200, 3100, 3760], { right: [1] }), afterTable());

// ====================================================================== 3.5
add(H2('3.5 Feature representations'));
add(H3('3.5.1 Hand-crafted descriptors'));
add(P(`Three classical descriptors were computed from the sequence. The amino acid composition (AAC) is the vector of the ${F.dim.aac} residue frequencies, and the dipeptide composition (DPC) is the vector of the ${F.dim.dpc} frequencies of ordered residue pairs ${cit('bhasin2004')}. The composition–transition–distribution (CTD) descriptor ${cit('dubchak1995')} assigns each residue to one of three classes for each of seven physicochemical properties (hydrophobicity, normalised van der Waals volume, polarity, polarisability, charge, secondary structure and solvent accessibility) and summarises the resulting three-letter sequence by the composition of the classes, the frequency of transitions between each pair of classes and the positions, as a percentage of the length, of the first, 25%, 50%, 75% and last occurrence of each class; this gives ${F.dim.ctd} values in total. The peptide length divided by 30 was added as one further feature. The hand-crafted set AAC+DPC+CTD+length has ${F.dim.hand} dimensions, and the compact set used by the composition baselines (AAC and length) has ${F.dim.aac_len}.`));
add(P(`Four classical baselines were trained on identical folds and evaluated under the same three regimes. An AAC support vector machine ${cit('cortes1995')} with a radial-basis kernel used a grid over the cost C (${F.par['baselines|SVM grid C'].replace(/[\[\]]/g, '')}) and the kernel width (${F.par['baselines|SVM grid gamma'].replace(/[\[\]]/g, '')}), chosen by three-fold cross-validated AUROC within the training fold. An AAC random forest ${cit('breiman2001')} used ${F.par['baselines|RandomForest n_estimators']} trees with balanced class weights. A gradient-boosted decision tree model (LightGBM; ${cit('ke2017')}) used the hand-crafted set, with up to ${lgb.n} trees, a learning rate of ${lgb.lr}, ${lgb.leaves} leaves per tree and early stopping after ${lgb.es} rounds without improvement on an inner 10% hold-out of the training fold. A logistic regression on the frozen ESM-2 embedding (Section 3.5.2) used a regularisation strength chosen by inner cross-validation. All features were standardised with a scaler fitted on the training fold only, so that no information from the validation data entered the preprocessing.`));
add(H3('3.5.2 ESM-2 embeddings and pooling variants'));
add(P(`Protein language model representations were obtained from the ESM-2 family ${cit('lin2023')}. Four checkpoints were used, listed in Table ${ref('tab:esm')}. Each was used strictly as a frozen feature extractor: the model was set to evaluation mode, no gradient was computed and no weight was changed. The final-layer hidden states of the real residue positions were averaged (Equation ${E('pool')}), where <b>h</b><sub>t</sub> is the hidden state at position <i>t</i> and ℛ is the set of real residue positions, excluding the <i>cls</i> and <i>eos</i> tokens and all padding.`));
add(eq('pool', R('e = '), frac([R('1')], [R('|ℛ|')]), sum([R('t∈ℛ')], null, sub('h', 't'))));
add(P(`Excluding the special tokens and the padding is a point at which implementations commonly err, so the extraction code asserts, with an absolute tolerance of 1e-4, that a sequence yields the same vector whether it is embedded alone or in a padded batch. Each of the ${n(F.n_unique_embedded)} unique sequences across the three datasets was embedded once and the vectors were cached, so that every model reads identical features. For the sequence models of Section 3.6 the same checkpoints were used to cache the residue-level vectors themselves (${n(F.residue_vectors)} residue vectors in total), together with the <i>cls</i> vector. The 8M cache was stored in single precision and the 650M cache in half precision; mean pooling of the cached residue vectors was compared with the pooled embedding computed directly for every one of the ${n(F.n_unique_embedded)} sequences (results/v2/half_precision_check.csv): the largest absolute difference was ${F.half.esm2_t33_650M.max_abs.toExponential(1)} for the half-precision 650M cache (${F.half.esm2_t33_650M.rel.toExponential(1)} of the largest embedding value) and ${F.half.esm2_t6_8M.max_abs.toExponential(1)} for the single-precision 8M cache.`));
add(P(`The extraction time of the 650M checkpoint is not reported in Table ${ref('tab:esm')}, because it was not reliably measurable: the extraction ran while the machine was short of memory and could not be repeated on an idle machine, since the 2.6 GB checkpoint did not fit in the disk space available at the time of the re-timing attempt. The times of the three smaller checkpoints are single measurements without repetition. Hardware, software versions and run times are described in Section 3.10.`));
add(caption('tab:esm', 'The ESM-2 checkpoints used as frozen feature extractors. Embedding times are single measurements for all unique sequences on the CPU of the machine used. Source: results/embedding_timings.csv and results/v2/methods_parameters.csv.'));
add(table(T.esm, [2300, 800, 1100, 1400, 2400, 1360], { right: [1, 3, 4, 5] }), afterTable());
add(P(`<b>Pooling variants.</b> Mean pooling over about sixteen residues may discard information that other summaries retain, so six pooling variants were compared on the frozen 650M checkpoint (Table ${ref('tab:pooling')}). Each pooled vector was classified by the same multilayer perceptron trained with the binary cross-entropy loss alone (λ = 0), on the same folds, with the scaler fitted on the training fold and early stopping on a 10% hold-out of the training fold. The attention variant, in which the weights over residues are learned jointly with the classifier, is model B6 of Section 3.6 applied to the 650M residue vectors.`));
add(caption('tab:pooling', 'Pooling variants compared on frozen ESM-2 650M embeddings. Dimensions from results/v2/pooling_dimensions.csv.'));
add(table(T.pooling, [1900, 6200, 1260], { right: [2] }), afterTable());
add(P(`<b>Feature fusion.</b> To test whether the language model and the hand-crafted descriptors carry complementary information, the mean-pooled ESM-2 vector was concatenated with the hand-crafted set (${F.fusion_dim.esm8} dimensions for the 8M checkpoint and ${n(F.fusion_dim.esm650)} for the 650M checkpoint) and classified by a random forest, LightGBM and the multilayer perceptron, each also trained on the ESM-2 vector alone and on the hand-crafted set alone, on identical folds and under the same three regimes.`));
add(H3('3.5.3 Fine-tuning protocol'));
add(P(`To test the design decision to keep the language model frozen, the 8M checkpoint was also fine-tuned end to end. A frozen-backbone control with the identical head, loop and folds was trained alongside it, so that the only difference between the two conditions is whether the backbone weights are updated. The backbone has ${T.layers.C3_finetune[1][2]} parameters and the head ${T.layers.C3_finetune[2][2]}. Residue hidden states were mean-pooled as in Equation ${E('pool')} and passed to a head of one hidden layer; the model was trained with the binary cross-entropy loss and the positive-class weight of Section 3.7, with a lower learning rate for the pretrained backbone than for the new head (Table ${ref('tab:finetune')}). Cross-validation used five folds for each of three seeds, and final models used five seeds, each with a stratified 10% hold-out for early stopping. The runs were executed on a graphics processing unit (${F.env['Kaggle GPU model']}) provided by the Kaggle platform, because fine-tuning on the central processor of the local machine was impractical; fine-tuning of the larger checkpoints was not attempted.`));
add(caption('tab:finetune', 'Fine-tuning protocol for the ESM-2 8M checkpoint and its frozen control. Source: results/v2/methods_parameters.csv.'));
add(table(T.finetune, [2600, 6760]), afterTable());

// ====================================================================== 3.6
add(H2('3.6 Model architectures'));
add(P(`Six architectures were compared under one protocol. All of them are sequence models: their input is a string of between ${F.i425.len_min} and ${F.bench.len_max} amino acids, represented here by the frozen ESM-2 8M embeddings of its residues, and their output is one probability per peptide. Detection-style architectures, such as YOLO or Faster R-CNN, are not applicable to this input. They operate on an image tensor with two spatial dimensions and output the coordinates of bounding boxes and class scores for objects in the image; a peptide has no spatial grid, contains no object to localise and has no box to regress, so there is nothing for such a model to detect. The appropriate sequence-domain counterparts of convolutional and recurrent image architectures are one-dimensional convolutions and recurrent or attention models over the residue axis, and these are the models compared.`));
add(P(`All six share the same output structure, which is the structure that the loss functions of Section 3.7 require: a shared encoder produces a vector of 256 dimensions, from which a classifier head (one linear unit) gives the logit for the binary cross-entropy loss and a projection head (128 dimensions, L2-normalised) gives the embedding for the contrastive loss. Model B1 is the multilayer perceptron on the mean-pooled vector, which is the reference point (Figure ${ref('fig:aipnet')}, Table ${ref('tab:layers_b1')}). In models B2–B5 a learned per-residue linear layer first reduces each residue vector to a ${F.par['Phase B residue-level models|per-residue adapter width']}-dimensional representation, before the sequence layers; this keeps the parameter count in proportion to the ${n(F.clean.n)} training sequences, limits overfitting, and made training feasible on the available hardware. Residue vectors were standardised feature by feature using the mean and standard deviation of the real residues of the training fold, and padding positions were masked in every pooling and attention operation. The total parameter count of each model is given in its layer table.`));
add(P(`The layers, shapes and parameter counts of all six models are listed in Tables ${ref('tab:layers_b1')} to ${ref('tab:layers_b6')} of Appendix B.`));
add(figure('fig:aipnet', 'fig3_3_architecture.png', 'The network used for the mean-pooled reference model B1. The frozen ESM-2 encoder is used as a feature extractor only; one shared encoder feeds two heads, so the cross-entropy gradient (solid) and the contrastive gradient (dashed) update the same representation. The weight lambda sets how much the contrastive term contributes.'.replace('lambda', '\u03bb'), 460));
const archTexts = [
  ['B1_mlp', 'B1: multilayer perceptron on the mean-pooled vector', `B1 is the reference model. The mean-pooled ESM-2 vector is standardised and passed through two blocks of a linear layer, batch normalisation ${cit('ioffe2015')}, a rectified linear unit and dropout ${cit('srivastava2014')}, with widths 512 and 256. It is the model against which the contrastive term is tested, and, because the heads and the losses are shared with the other models, setting λ = 0 gives exactly the same network trained with the cross-entropy loss alone.`],
  ['B2_cnn', 'B2: one-dimensional convolutional network', `B2 applies three parallel one-dimensional convolutions with kernel sizes of 3, 5 and 7 residues to the adapted residue vectors, each followed by a rectified linear unit and a masked global maximum over positions. The kernels respond to local residue motifs, and the maximum makes the response independent of where in the peptide a motif occurs. This is the sequence-domain analogue of a convolutional image network.`],
  ['B3_bilstm', 'B3: bidirectional long short-term memory network', `B3 passes the adapted residue vectors through a two-layer bidirectional LSTM ${cit('hochreiter1997')} using packed sequences, so that padding does not enter the recurrence, and uses the final forward and backward states of the top layer. It models the order of residues in both directions, which pooling discards.`],
  ['B4_cnn_bilstm', 'B4: convolutional network followed by a bidirectional LSTM', `B4 combines the two preceding ideas: a convolution extracts local motifs from the adapted residue vectors and a one-layer bidirectional LSTM models their order, with a masked maximum over positions of the recurrent outputs. The hybrid tests whether local motifs and residue order carry information that either alone does not.`],
  ['B5_transformer', 'B5: Transformer encoder', `B5 adds a learned positional embedding to the adapted residue vectors and applies a two-layer Transformer encoder with four attention heads ${cit('vaswani2017')} and a key-padding mask, followed by a masked mean over positions. The encoder layers are trained from scratch on top of the frozen language model features. The model tests whether attention among at most thirty residues helps at this data scale.`],
  ['B6_attnpool', 'B6: attention pooling', `B6 replaces the mean in Equation ${E('pool')} with a learned weighted average: a small network scores each residue and a masked softmax turns the scores into weights ${cit('ilse2018')}. The pooled vector then enters the same 512–256 encoder as B1. Because everything after pooling is identical to B1, the comparison of B1 and B6 isolates the pooling step from the rest of the architecture.`],
];
archTexts.forEach(([key, title, text]) => {
  add(H3(`3.6.${archTexts.findIndex((a) => a[0] === key) + 1} ${title}`));
  add(P(text));
});
add(P(`Each architecture was trained at λ = 0 and at the value of λ that gave the highest cross-validated MCC (Section 3.9), so that the comparison of the contrastive objective is repeated in every architecture. Models B1, B3, B4 and B6 were trained on the central processor of the local machine and models B2 and B5 on graphics processors; the λ = 0 baseline and every λ value of a given architecture were always trained on the same type of device.`));

// ====================================================================== 3.7
add(H2('3.7 Loss functions'));
add(H3('3.7.1 Binary cross-entropy with a positive-class weight'));
add(P(`The classification loss for a mini-batch of <i>B</i> peptides with labels <i>y</i><sub>i</sub> ∈ {0, 1} and logits ℓ<sub>i</sub> is the weighted binary cross-entropy of Equation ${E('bce')}, where σ is the logistic function and the weight of the positive class is <i>w</i> = <i>n</i><sub>neg</sub> / <i>n</i><sub>pos</sub>, computed from the training fold only. On Benchmark_clean as a whole this ratio is ${F.pos_weight_clean.toFixed(3)} (${n(F.clean.neg)} non-AIPs to ${n(F.clean.pos)} AIPs); the weight compensates for the class imbalance without resampling.`));
add(eq('bce', sub('L', 'BCE'), R(' = −'), frac([R('1')], [R('B')]), sum([R('i=1')], [R('B')], sq(R('w '), sub('y', 'i'), fn('log', [R('σ'), par(sub('ℓ', 'i'))]), R(' + '), par(R('1 − '), sub('y', 'i')), fn('log', [par(R('1 − σ'), par(sub('ℓ', 'i')))])))));
add(H3('3.7.2 Supervised contrastive loss'));
add(P(`The contrastive term follows the supervised contrastive formulation of ${citN('khosla2020')} in its form with the average taken outside the logarithm. Let <b>z</b><sub>i</sub> be the L2-normalised output of the projection head for peptide <i>i</i> in a mini-batch with index set <i>I</i>, so that the inner product of two such vectors is their cosine similarity. For an anchor <i>i</i>, let <i>A</i>(<i>i</i>) = <i>I</i> \\ {<i>i</i>} be all other peptides in the batch and let <i>P</i>(<i>i</i>) = {<i>p</i> ∈ <i>A</i>(<i>i</i>) : <i>y</i><sub>p</sub> = <i>y</i><sub>i</sub>} be the other peptides that share the anchor's label. With a temperature τ the loss is given by Equation ${E('supcon')}, where <i>I</i><sup>+</sup> is the set of anchors for which <i>P</i>(<i>i</i>) is not empty.`));
add(eq('supcon', sub('L', 'SupCon'), R(' = '), frac([R('1')], [R('|I⁺|')]), sum([R('i∈I⁺')], null, par(R('−'), frac([R('1')], [R('|P(i)|')]), sum([R('p∈P(i)')], null, fn('log', [frac([fn('exp', [par(sub('z', 'i'), R('·'), sub('z', 'p'), R('/τ'))])], [sum([R('a∈A(i)')], null, fn('exp', [par(sub('z', 'i'), R('·'), sub('z', 'a'), R('/τ'))]))])]))))));
add(P(`Because the embeddings were computed in advance and are frozen, the usual construction of two augmented views of each sample is not available; the labels alone define the positives, so the loss is well defined with one view per sample, and this single-view form was the one used in the pre-specified experiments. Three implementation details matter. The similarity of an anchor with itself is excluded from the denominator by masking the diagonal. The largest off-diagonal logit in each row is subtracted before exponentiation for numerical stability. Anchors with no positive in the batch contribute nothing and are skipped, instead of producing an undefined value. The implementation was verified against a naive loop implementation of Equation ${E('supcon')} and by tests of the properties described in Section 3.7.4.`));
add(H3('3.7.3 Combined objective and the roles of λ and τ'));
add(P(`The two losses are combined as in Equation ${E('comb')}. The weight λ is the ablation axis of the study: λ = 0 removes the contrastive term and gives the cross-entropy baseline, and each λ > 0 adds it with that weight. Both gradients flow into the same encoder, which is the mechanism by which the contrastive term can reshape the representation that the classifier reads. The cross-entropy baseline and the contrastive model are the same code path, differing only in the value of λ: the contrastive loss is computed at every step and multiplied by λ, so that λ = 0 reproduces the baseline exactly and its value can still be logged. The grid for λ was ${F.par['v1 AIPNet / training loop|lambda_grid'].replace(/[\[\]]/g, '')}, and it was not extended.`));
add(eq('comb', R('L = '), sub('L', 'BCE'), R(' + λ '), sub('L', 'SupCon')));
add(P(`The temperature τ controls how sharply the loss concentrates on the hardest comparisons: a small τ weights near-misses heavily and a large τ treats all pairs more evenly. The grid ${F.par['v1 AIPNet / training loop|temperature_grid'].replace(/[\[\]]/g, '')} was examined for the multilayer perceptron at each checkpoint, at the value of λ that was best in cross-validation, and τ was fixed at ${F.par['Phase B residue-level models|temperature']} for the architecture comparison of Section 3.6.`));
add(H3('3.7.4 The analytic floor of the contrastive loss'));
add(P(`The supervised contrastive loss does not approach zero when the embedding is good. Write <i>s</i><sub>ia</sub> = <b>z</b><sub>i</sub> · <b>z</b><sub>a</sub> / τ. The per-anchor term of Equation ${E('supcon')} can be rewritten as Equation ${E('perAnchor')}. The denominator of the logarithm contains the positives themselves, so the first term is at least the logarithm of the sum over the positives, which by Jensen's inequality is at least log |<i>P</i>(<i>i</i>)| plus the mean positive similarity; subtracting the mean positive similarity leaves the bound of Equation ${E('floor')}, with equality only when all positives are equally similar to the anchor and every negative contributes nothing.`));
add(eq('perAnchor', sub('ℓ', 'i'), R(' = '), fn('log', [sum([R('a∈A(i)')], null, fn('exp', [par(sub('s', 'ia'))]))]), R(' − '), frac([R('1')], [R('|P(i)|')]), sum([R('p∈P(i)')], null, sub('s', 'ip'))));
add(eq('floor', sub('ℓ', 'i'), R(' ≥ '), fn('log', [R('|P(i)|')])));
add(P(`With a mini-batch of ${F.par['v1 AIPNet / training loop|batch_size']} peptides and the class balance of Benchmark_clean (${pct(F.clean.pos_rate)} AIPs), a positive anchor has on average ${F.floor['positive anchor'].npos.toFixed(2)} positives and the floor is ${F.floor['positive anchor'].floor.toFixed(3)}, and a negative anchor has ${F.floor['negative anchor'].npos.toFixed(2)} positives and a floor of ${F.floor['negative anchor'].floor.toFixed(3)} (results/v2/supcon_floor.csv). The loss in a perfectly clustered embedding is therefore about 3.9 to 4.4, not zero, and a reduction of the training contrastive loss is bounded from below by these values. Only when every anchor has exactly one positive does the floor reach zero, which was one of the cases used in the unit tests of the implementation; the tests also confirmed the floor of log 7 for a batch with eight peptides per class, a markedly higher loss when the labels are permuted, finite values for a single-class batch and the flow of gradients to the input.`));
add(H3('3.7.5 Training protocol'));
add(P(`The models were trained with the AdamW optimiser ${cit('loshchilov2017')} with a cosine learning-rate schedule ${cit('loshchilov2016')}, a batch size of ${F.par['v1 AIPNet / training loop|batch_size']} (the contrastive loss needs many in-batch positives) and early stopping on the MCC of the validation fold with a patience of ${F.par['v1 AIPNet / training loop|patience']} epochs, restoring the best weights (Table ${ref('tab:training')}). Five-fold stratified cross-validation was performed on Benchmark_clean; each fold trained on about ${n(F.train_fold_n)} sequences and validated on about ${F.val_fold_n}. The folds were produced by one shared function and were re-drawn for each of five seeds, so that every model, deep or classical, saw the same partitions, and the seed also fixed the initial weights, the batch order and the dropout masks, so that the λ = 0 and λ > 0 models of the same seed differ only in the loss. Standardisation was fitted on the training fold only. Cross-validation therefore produced 25 runs (five folds for each of five seeds) per configuration.`));
add(figure('fig:splits', 'fig3_5_splitting.png', 'Cross-validation and splitting protocol. Each of the five folds is held out in turn (cross-hatched); the scaler and the positive-class weight are fitted on the training part of that fold only and then applied to the held-out part, so no information from the held-out peptides reaches the model. The folds are redrawn for each of five seeds, giving 25 runs per configuration. Final models (dashed) are trained on all of Benchmark_clean with a stratified 10 per cent hold-out for early stopping.', 470));

add(P(`Final models for the independent sets were trained on all of Benchmark_clean, with a stratified 10% of it held out for early stopping, for each of five seeds, and each was evaluated on both independent sets under the three regimes. For paired testing the predicted probabilities of the five seeds were averaged into one ensemble prediction per model, with the class assigned at a threshold of 0.5; a second threshold, tuned on the hold-out only and never on test data, was applied in separate tables. In the cross-validation of the residue-level models the validation fold also served for early stopping, as it did for the multilayer perceptron; this is mildly optimistic but identical across λ values and therefore does not favour either side of the comparison.`));
add(caption('tab:training', 'Training settings of the multilayer perceptron and of the residue-level models. Source: results/v2/methods_parameters.csv.'));
add(table(T.training, [3400, 5960]), afterTable());

// ====================================================================== 3.8
add(H2('3.8 Evaluation metrics'));
add(P(`Eight metrics were computed for every model, regime and run, with AIP as the positive class. Let TP, TN, FP and FN be the numbers of true positives, true negatives, false positives and false negatives. Accuracy, sensitivity (recall of AIPs), specificity (recall of non-AIPs), precision and the F1 score are given in Equations ${E('acc')} to ${E('f1')}, and the Matthews correlation coefficient (MCC; ${citN('matthews1975')}) in Equation ${E('mcc')}.`));
add(eq('acc', R('Accuracy = '), frac([R('TP + TN')], [R('TP + TN + FP + FN')])));
add(eq('sens', R('Sensitivity = '), frac([R('TP')], [R('TP + FN')])));
add(eq('spec', R('Specificity = '), frac([R('TN')], [R('TN + FP')])));
add(eq('prec', R('Precision = '), frac([R('TP')], [R('TP + FP')])));
add(eq('f1', sub('F', '1'), R(' = '), frac([R('2 · Precision · Sensitivity')], [R('Precision + Sensitivity')])));
add(eq('mcc', R('MCC = '), frac([R('TP·TN − FP·FN')], [M.rad([R('(TP+FP)(TP+FN)(TN+FP)(TN+FN)')])])));
add(P(`The area under the receiver operating characteristic curve (AUROC) is the probability that a randomly chosen AIP receives a higher score than a randomly chosen non-AIP, with ties counted as one half (Equation ${E('auroc')}), and the area under the precision–recall curve (AUPRC) is estimated by the average precision (Equation ${E('auprc')}), where <i>P</i><sub>n</sub> and <i>R</i><sub>n</sub> are the precision and recall at the <i>n</i>-th threshold. A value of 0 was assigned to a metric whose denominator was zero, and AUROC and AUPRC were undefined for a set with a single class.`));
add(eq('auroc', R('AUROC = P'), par(sub('s', '+'), R(' > '), sub('s', '−')), R(' + '), frac([R('1')], [R('2')]), R('P'), par(sub('s', '+'), R(' = '), sub('s', '−'))));
add(eq('auprc', R('AUPRC = '), sum([R('n')], null, par(sub('R', 'n'), R(' − '), sub('R', 'n−1')), sub('P', 'n'))));
add(P(`The MCC is the primary metric because the classes are imbalanced: only ${pct(F.clean.pos_rate)} of Benchmark_clean and ${pct(F.i425.pos_rate)} and ${pct(F.i1049.pos_rate)} of the independent sets are AIPs, so a classifier that labels every peptide as a non-AIP attains an accuracy of ${pct(F.majority_accuracy_clean)} on the training collection while detecting nothing. The MCC uses all four cells of the confusion matrix, equals zero for a classifier that is no better than chance whatever the class proportions, and is large only when the classifier does well on both classes. Accuracy, precision, F1 and the AUPRC depend on the class proportions of the test set, which differ slightly between regimes (Table ${ref('tab:regimes')}), whereas the AUROC does not and the MCC depends on them less than the other threshold-based metrics. The AUPRC is reported in addition because its baseline equals the class prevalence, which makes it informative under imbalance. The decision threshold for the headline results was 0.5; the AUROC and AUPRC do not depend on it.`));

// ====================================================================== 3.9
add(H2('3.9 Statistical protocol'));
add(H3('3.9.1 The pre-registered hypothesis'));
add(P(`The primary hypothesis was written down and committed after the audit of Phase A and before the experiments of Phases B to F were run. <b>H1:</b> at the ESM-2 8M checkpoint, a classifier trained with the cross-entropy loss plus λ times the supervised contrastive loss (λ > 0) has a higher MCC than the identical classifier trained with the cross-entropy loss alone, on the leakage-free (Regime B) versions of both Ind_425 and Ind_1049. The test that settles it is the paired difference in MCC (ensemble predictions, threshold 0.5, the model at the cross-validation-selected λ minus the model at λ = 0) with a 95% paired stratified bootstrap confidence interval; H1 is supported if and only if the lower bound of the interval is above zero on both test sets, an intersection–union rule that needs no correction for multiplicity at the 5% level. The document that fixes the hypothesis, the decision rule and the protocol is stored under commit ${F.prereg_commit}.`));
add(P(`The preregistration states a limitation that is repeated here: the H1 test had already been run in the first part of the study, and its outcome was known, when the document was written, so the document fixes the analysis plan and prevents later promotion of other results, but it cannot claim that H1 was tested blind. The comparison of λ > 0 with λ = 0 repeated for each of the architectures B2–B6 on both test sets in Regime B (ten comparisons) was designated H2, a secondary hypothesis, with the rule that a comparison counts as support only if its Benjamini–Hochberg-adjusted DeLong p-value is below 0.05 and the lower bound of the interval of its MCC difference is above zero. Everything else, including the results for Regimes A and C, for checkpoints other than 8M, the pooling, fusion and fine-tuning experiments and the analyses of the errors and of the data, was designated exploratory and is labelled as such in every table.`));
add(H3('3.9.2 Paired tests'));
add(P(`Two models evaluated on the same sequences produce correlated predictions, so their difference was tested with paired procedures. The AUROCs of two models were compared with DeLong's test ${cit('delong1988')}, which estimates the covariance of the two correlated AUROC estimates from the structural components of the U-statistic (Equation ${E('delong')}); the variance was computed from the midranks, not approximated by resampling. Here AUC<sub>a</sub> and AUC<sub>b</sub> are the two estimates and the variance of their difference is estimated from the sample covariance of the structural components. The accuracy of two models was compared with McNemar's test ${cit('mcnemar1947')} on the cases in which exactly one of them is correct. With <i>b</i> cases correct only for the first model and <i>c</i> correct only for the second, the exact two-sided binomial probability of Equation ${E('mcnemar')} was used when <i>b</i> + <i>c</i> was below ${F.par['statistics|McNemar exact-test cut-off (discordant pairs)']}, and a chi-square statistic with continuity correction otherwise. Both tests were applied to the seed-ensemble predictions, one prediction vector per model; the variation between seeds is reported separately, as the difference in MCC and AUROC for each seed and as the number of seeds in which the difference is positive, because the ensemble comparison reflects sampling variation of the test peptides only and ignores training variation.`));
add(eq('delong', R('z = '), frac([sub('AUC', 'a'), R(' − '), sub('AUC', 'b')], [new MathRadical({ children: [fn('Var', [par(sub('AUC', 'a'), R(' − '), sub('AUC', 'b'))])] })])));
add(eq('mcnemar', R('p = 2 '), sum([R('k=0')], [R('min(b,c)')], R('C(b+c, k) '), sup('0.5', 'b+c'))));
add(H3('3.9.3 Confidence intervals and effect sizes'));
add(P(`Confidence intervals for the AUROC, for the MCC and for their paired differences were obtained by a stratified bootstrap with ${n(F.par['statistics|bootstrap resamples'])} resamples ${cit('efron1979')}, in which AIPs and non-AIPs were resampled separately to preserve the class balance and, for paired differences, both models were scored on the same resample. The 2.5th and 97.5th percentiles gave the 95% interval. Every p-value was reported with the effect it tests and the interval of that effect, so that the size of a difference is never inferred from its significance alone. For paired cross-validation differences (same seed and fold) the standardised paired difference <i>d</i><sub>z</sub>, the mean difference divided by its standard deviation, was reported; the 25 folds overlap in their training data, so the intervals derived from them are optimistic and are not used for claims.`));
add(H3('3.9.4 Multiplicity'));
add(P(`In total ${F.n_comparisons} paired comparisons were tabulated across the experiments, and a p-value from a family of that size is not interpretable on its own. The Benjamini–Hochberg procedure ${cit('benjamini1995')} controls the false discovery rate: with <i>m</i> p-values sorted in increasing order, the adjusted value of the <i>i</i>-th is given by Equation ${E('bh')}. Adjustment was applied at a false discovery rate of ${F.par['statistics|BH false-discovery rate q']} within each family (the architecture comparison H2; all contrasts of λ > 0 with λ = 0; the representation comparisons of pooling, fusion and fine-tuning) and globally across every secondary and exploratory test, and the raw and the adjusted p-values are given side by side in the results tables. Only comparisons in Regime B could support a claim; results in Regime A are reported for comparability only.`));
add(eq('bh', new MathSubSuperScript({ children: [R('p')], subScript: [R('(i)')], superScript: [R('adj')] }), R(' = '), new MathSubScript({ children: [R('min')], subScript: [R('j ≥ i')] }), par(frac([R('m')], [R('j')]), R(' '), sub('p', '(j)'))));
add(H3('3.9.5 Power and the minimum detectable effect'));
add(P(`A non-significant result is informative only in relation to the effect that the test could have detected. For each paired comparison the standard deviation of the bootstrap distribution of the difference was taken as its standard error, SE, and the minimum detectable effect at a power of ${F.par['statistics|power for minimum detectable effect']} and a two-sided significance level of ${F.par['statistics|two-sided alpha']} was computed as in Equation ${E('mde')}, with z<sub>1−α/2</sub> = 1.96 and z<sub>1−β</sub> = 0.84 (Table ${ref('tab:mde')}). The calculation applies to paired comparisons of two models scored on the same sequences, which is the design of every test in this study; an unpaired comparison would require a larger difference. A non-significant difference is accordingly reported as the absence of a detectable effect larger than the minimum detectable effect at that sample size, never as evidence that the two models are equivalent.`));
add(eq('mde', R('MDE = '), par(sub('z', '1−α/2'), R(' + '), sub('z', '1−β')), R(' · SE')));
add(caption('tab:mde', 'Minimum detectable effect (80% power, two-sided α = 0.05) of the paired comparisons of λ > 0 with λ = 0 for each test set and regime. Source: results/v2/mde_summary.csv, derived from results/tables/T5.11_corrected_significance.csv.'));
add(table(T.mde, [1300, 900, 1200, 1300, 3000, 1660], { right: [2, 3] }), afterTable());
add(H3('3.9.6 Nested cross-validation'));
add(P(`Because λ was selected by cross-validation on the same folds that were then used to report performance, the headline comparison was repeated with nested cross-validation, in which selection is separated from evaluation. In the outer loop the five folds and five seeds of the main protocol were used. For each outer training set, λ was chosen from the grid by the mean MCC over an inner three-fold cross-validation, and the model at the selected λ and the model at λ = 0 were then trained on the whole outer training set and scored on the outer fold, which had played no part in the selection or in early stopping. This gave 25 paired outer-fold results for the 8M multilayer perceptron.`));
add(P(`The remainder of this chapter describes how these procedures were implemented and run: the hardware and software, the organisation of the experiments and the compute time they required, the hyperparameters and their search ranges, the training protocol, the pre-registration, and the measures taken for reproducibility. It also lists the places where the execution departed from the plan, because a reader who wants to repeat or extend the work needs to know them. The results obtained with these procedures are reported in Chapter 4.`));

add(H2('3.10 Hardware and Software Environment'));
add(P(`Most of the work was carried out on a single laptop-class machine with an ${env['local machine']} processor with ${env['local logical cores']} cores and ${gib} GiB of memory, running ${env['local OS'].replace('macOS-', 'macOS ').split('-')[0]}, with Python ${A.python}. Two experiments, the training of the convolutional and Transformer architectures and the fine-tuning of the language model, were run on graphics processors provided by the Kaggle platform: a kernel with two ${env['Kaggle GPU model']} GPUs, Python ${env['Kaggle kernel python and torch'].split(' ')[0]} and PyTorch ${env['Kaggle kernel python and torch'].split(' ')[1]}, without internet access, so that the code, the cached embeddings and the 8M model weights were supplied as a private dataset. The main software packages and their versions are listed in Table ${ref('tab:software')}; the full list of pinned versions is in the file requirements.txt of the project.`));
const sw = [['Package', 'Version', 'Use'],
  ['PyTorch', req.torch, `neural network training ${cit('paszke2019')}`], ['Transformers (Hugging Face)', req.transformers, 'loading and running ESM-2'],
  ['scikit-learn', req['scikit-learn'], `classical models, folds, metrics ${cit('pedregosa2012')}`], ['LightGBM', req.lightgbm, `gradient-boosted trees ${cit('ke2017')}`],
  ['NumPy / pandas / SciPy', `${req.numpy} / ${req.pandas} / ${req.scipy}`, 'numerical work and statistics'], ['Biopython', req.biopython, `pairwise alignment for the identity screen ${cit('cock2009')}`],
  ['RapidFuzz', req.RapidFuzz, 'longest-common-subsequence prefilter'], ['Matplotlib / seaborn', `${req.matplotlib} / ${req.seaborn}`, 'figures']];
add(caption('tab:software', 'Main software packages and versions on the local machine (from requirements.txt). The Kaggle kernels used their pre-installed PyTorch and scikit-learn.'));
add(table(sw, [2400, 2000, 4960]), afterTable());
add(P(`The ESM-2 checkpoints were obtained through the Transformers library ${cit('wolf2020')} from the model hub; each checkpoint was deleted from the local cache after its embeddings had been extracted, because the machine had little free disk space. The experiments were scheduled around the memory limit of the machine: the extraction of the largest checkpoint and the training of the models were not run concurrently after an early attempt showed that the combination exhausted the memory and slowed both.`));

add(H2('3.11 Organisation of the Experiments and Compute Time'));
add(P(`The experiments were organised as a sequence of stages, each writing its results to files on disk and recording a marker, so that an interrupted run could resume without repeating completed work. The first part of the study (stages S1 to S12) covered the data pipeline, the embeddings of the four checkpoints, the baselines, the sweeps of λ and τ, the final models, the statistics, and the tables and figures. The second part added the audit of provenance and overlap (Phase A), the pre-registration, the residue-level embeddings, the six architectures (Phase B), the pooling, fusion and fine-tuning studies (Phase C), the cross-benchmark analysis (Phase D), the corrected statistics, the nested cross-validation (Phase E) and the analysis of the data and of the errors (Phase F). The compute time recorded for each stage is given in Table ${ref('tab:stages')} of Appendix B.`));
add(P(`The cost of training a single model depends strongly on the architecture and on the device. On the central processor, a five-fold cross-validation run of the bidirectional LSTM (B3) took on average ${A.b_seconds.B3_bilstm.toFixed(0)} seconds and one of the hybrid convolutional and recurrent network (B4) ${A.b_seconds.B4_cnn_bilstm.toFixed(0)} seconds, whereas on the graphics processor a run of the convolutional network (B2) took ${A.b_seconds.B2_cnn.toFixed(0)} seconds and one of the Transformer (B5) ${A.b_seconds.B5_transformer.toFixed(0)} seconds. A fine-tuning run of the 8M language model took on average ${A.ft_seconds.finetune.toFixed(0)} seconds on the graphics processor, and a run of the frozen-backbone control ${A.ft_seconds.frozen.toFixed(0)} seconds. Table ${ref('tab:devices')} records on which device each architecture was trained; the λ = 0 model and every λ value of one architecture were always trained on the same type of device.`));
const dev = [['Experiment', 'Device']];
const nm = { B1_mlp: 'B1 MLP (first part of the study)', B2_cnn: 'B2 CNN', B3_bilstm: 'B3 BiLSTM', B4_cnn_bilstm: 'B4 CNN-BiLSTM', B5_transformer: 'B5 Transformer', B6_attnpool: 'B6 attention pooling', C3_finetune: 'C3 fine-tuning and frozen control' };
for (const [k, v] of Object.entries(A.device_map)) dev.push([nm[k] || k, v.replace(' (Kaggle duplicate ignored)', '')]);
add(caption('tab:devices', 'Device on which each architecture and the fine-tuning experiment were trained (results/v2/device_map.json).'));
add(table(dev, [3300, 6060]), afterTable());

add(H2('3.12 Hyperparameters and Search Ranges'));
add(P(`The hyperparameters of the neural models were fixed in advance and shared by every configuration (Table ${ref('tab:hyper')}); only λ and τ were searched, over the grids pre-specified in Section 3.7.3. Within a checkpoint or architecture, λ* was the value of λ > 0 with the highest mean cross-validated MCC over the 25 runs, with ties going to the smaller value, and τ* was then chosen from the temperature grid at λ*, as the value with the highest mean cross-validated MCC. For the architecture comparison τ was fixed at ${F.par['Phase B residue-level models|temperature']}. No hyperparameter of any model was chosen on an independent test set. The selected values are reported with the results in Chapter 4: λ* = ${A.selected_v2.B2_cnn.lambda_star} for B2 and λ* = ${A.selected_v2.B3_bilstm.lambda_star} for B3, B4, B5 and B6, and, in the multilayer perceptron at the four checkpoints, λ* = ${A.selected_v1['esm2_t6_8M_lam2_tau0.1'].lambda} (8M, τ* = ${A.selected_v1['esm2_t6_8M_lam2_tau0.1'].tau}), ${A.selected_v1['esm2_t12_35M_lam0.5_tau0.07'].lambda} (35M), ${A.selected_v1['esm2_t30_150M_lam2_tau0.07'].lambda} (150M) and ${A.selected_v1['esm2_t33_650M_lam1_tau0.05'].lambda} (650M, τ* = ${A.selected_v1['esm2_t33_650M_lam1_tau0.05'].tau}).`));
add(caption('tab:hyper', 'Training hyperparameters and search ranges. Source: results/v2/methods_parameters.csv.'));
add(table(T.training, [3400, 5960]), afterTable());
add(P(`The classical baselines were tuned inside the training fold. The support vector machine used a grid over C (${F.par['baselines|SVM grid C'].replace(/[\[\]]/g, '')}) and the kernel width (${F.par['baselines|SVM grid gamma'].replace(/[\[\]]/g, '')}) with three-fold cross-validated AUROC; the random forest used ${F.par['baselines|RandomForest n_estimators']} trees; LightGBM stopped early on an inner 10% hold-out of the training fold; and the logistic regression chose its regularisation strength by inner cross-validation. The residue-level models used a ${F.par['Phase B residue-level models|per-residue adapter width']}-dimensional per-residue adapter, a hidden size of 64 per direction in the recurrent layers, and gradient clipping at a maximum norm of ${F.par['Phase B residue-level models|clip']}.`));

add(H2('3.13 Training Protocol'));
add(P(`Cross-validation used five stratified folds, redrawn for each of five seeds, so that each configuration was trained 25 times (Section 3.7.5); the exception is the fine-tuning experiment, which used three repetition seeds (15 runs per mode) because of its cost. The folds were generated by one shared function, which every deep and classical model called, so that all models were trained and validated on exactly the same peptides. The weights, the order of the mini-batches and the dropout masks of a run were fixed by a seed derived from the repetition seed and the fold, so that two models that differ only in λ started from the same weights and saw the same batches.`));
add(P(`<b>Standardisation inside the fold.</b> The features were standardised with a scaler that was fitted on the training part of each fold only and then applied to the validation part. Fitting the scaler on all the data before splitting is a form of leakage: the mean and standard deviation of the validation peptides would influence the representation on which the model is trained, and the validation score would no longer be an estimate of performance on peptides that were not seen. The effect is small for a scaler, but it is the kind of effect that this thesis is concerned with, and the protocol excludes it by construction. The same rule applies to the positive-class weight of the cross-entropy loss, which was computed from the training fold only.`));
add(P(`Training stopped when the validation MCC had not improved for ${F.par['v1 AIPNet / training loop|patience']} epochs, and the weights of the best epoch were restored. In the cross-validation of the multilayer perceptron and of the residue-level models the validation fold served for this stopping rule; for the pooling and fusion studies, which were run later, the stopping rule used an inner 10% hold-out of the training fold, so that the validation fold took no part in training decisions. The first choice is mildly optimistic but identical across the λ values compared. Final models, trained on all of Benchmark_clean with a stratified 10% hold-out for early stopping, were trained for five seeds; their predicted probabilities were averaged into one ensemble prediction per model for the paired tests, and each seed was also scored separately so that variation between seeds could be reported. The fine-tuning experiment used its own loop: the whole 8M backbone was updated with a learning rate of 5e-5 and the head with 1e-3, with batches of 32, at most 8 epochs and early stopping on the validation MCC with a patience of 3 epochs; the frozen-backbone control used the same head, loop and folds with the backbone fixed. Both modes stopped on the validation fold, which is slightly optimistic and identical for both. Decisions that are not reversible on test data, such as the decision threshold, were never tuned on the independent sets: the headline threshold is 0.5, and a threshold tuned on the training hold-out was applied only in separate tables.`));

add(H2('3.14 Pre-registration and Analysis Tiers'));
add(P(`The primary hypothesis, its decision rule and the fixed protocol of the extended experiments were committed to the project repository after the audit of Phase A and before the residue-level, pooling, fusion, fine-tuning and cross-benchmark experiments were run, under commit ${A.prereg_commit}, which was pushed at ${A.prereg_time} on the day of the extended experiments. The document designates one primary hypothesis (H1), one secondary family of ten comparisons (H2) and, as exploratory, everything else, and every table of results carries the tier of its analyses. The document records that the H1 test had already been run in the first part of the study, so that the pre-registration fixes the analysis plan but does not make H1 a blind test (Section 3.9). One comparison was added after the data were examined, fine-tuned 8M against the frozen 650M model, to answer a question that arose from the results; it was placed in the exploratory family and included in the correction for multiple testing, which was re-run (${A.n_tests} comparisons in all).`));

add(H2('3.15 Reproducibility'));
add(P(`Every stage reads and writes files at fixed locations, every random seed is set explicitly, and the versions of the software are pinned. The cleaned training collection and the three evaluation regimes are stored as files, the embeddings of every checkpoint are cached and are computed once from the unique sequences of the three datasets, and the cross-validation folds are produced by a deterministic function of the seed. All results are written to files before they are tabulated, and every number in the following chapters can be traced to a results file, with the exception of numbers quoted from the literature. The code, the pinned requirements, the generated tables and figures and the results files are stored in a version-controlled repository (aip-supcon) with a commit history that records the order in which the experiments were run. The downloaded copies of the AIPpred, PreAIP and AntiInflam datasets are not redistributed; their addresses and SHA-256 digests are recorded so that they can be retrieved and checked. The repository is public at https://github.com/mohammad-sayem-uddin/aip-supcon (visibility checked on 2026-11-26). <todo>a permanent archive identifier (for example a Zenodo DOI for the submitted commit) has not been created; this needs the author's own account</todo>`));
add(P(`Two limits on exact reproducibility should be stated. The convolutional and Transformer architectures and the fine-tuning ran on graphics processors, whose floating-point reductions are not bit-identical to those of the central processor, so that repeating those runs reproduces the results to within seed-level variation, not bit by bit. The extraction time of the 650M checkpoint was not recorded reliably, and the time-consuming parts of Phase B on the local machine were run in slices that were not timed as a whole.`));

add(H2('3.16 Deviations from the Plan and Problems Encountered'));
add(P(`The following departures from the original plan are recorded so that the reader can judge their effect. The residue-level architectures use a ${F.par['Phase B residue-level models|per-residue adapter width']}-dimensional learned adapter and 64 hidden units per direction, instead of 128, because unadapted inputs made a single fold impractical on the available processor; this choice was made before any Phase B result was seen. The temperature was fixed at ${F.par['Phase B residue-level models|temperature']} for Phase B, and the temperature sweep was not repeated for the new architectures. Phase B was split across devices as shown in Table ${ref('tab:devices')}. Because the machine had little memory and disk space, the 650M embeddings were extracted once and the checkpoint was deleted afterwards, which is why its extraction could not be timed again. A resume routine in the experiment runner initially mis-matched saved runs and re-ran 22 cross-validation runs of the hybrid network; the duplicates were removed, the original rows were kept and the routine was corrected. Finally, three planned elements were only partly completed: the independent sets of AIPStack could not be obtained; the comparison with other protein language models was completed for ProtT5-XL (encoder) but not for ProtBERT, whose kernel produced only downloaded weights rather than computed embeddings (Section 4.6.4); and the transfer of the method to other peptide families was not attempted (Chapter 4, Section 4.10).`));



add(H2('3.17 Summary'));
add(P(`This chapter described both the methods and their implementation. It established the provenance of the three distributed files and audited them for duplication, label conflict and overlap; defined the cleaning that produced Benchmark_clean and the three evaluation regimes that progressively remove training-test overlap; specified the hand-crafted descriptors and the frozen ESM-2 embeddings with their pooling variants; defined the six architectures, the two loss functions and the weight that combines them; and fixed the metrics and the statistical protocol, including the pre-registered hypothesis, the correction for multiple testing and the minimum detectable effect. It then described the hardware and software, the compute time, the hyperparameters and their search ranges, the training protocol, the pre-registration and the reproducibility arrangements, and recorded the points at which execution departed from the plan. The results obtained under these procedures are reported in Chapter 4.`));

L.build().then(() => console.log('equations', eqSeen));

module.exports = L;
